/* Browser-local learning and DEMO rewards; never an authenticated wallet. */
(()=>{const key='bunny-academy-v1',blank=()=>({step:0,completed:false}),valid=s=>s&&Number.isInteger(s.step)&&s.step>=0&&s.step<=7&&typeof s.completed==='boolean',clean=s=>valid(s)?{step:s.step,completed:s.completed}:blank();const read=()=>{try{const s=JSON.parse(localStorage.getItem(key)||'null');return {version:1,lessonOne:clean(s?.lessonOne),lessonTwo:clean(s?.lessonTwo)}}catch{return{version:1,lessonOne:blank(),lessonTwo:blank()}}};const write=s=>{try{localStorage.setItem(key,JSON.stringify(s));return true}catch{return false}};const save=(lesson,step)=>{if(!Number.isInteger(step)||step<0||step>7)return false;const s=read();s[lesson].step=step;return write(s)};const complete=lesson=>{const s=read();if(s[lesson].step!==7)return{ok:false};const prior=s[lesson].completed;s[lesson].completed=true;const ok=write(s);if(ok)try{localStorage.setItem('bunny-interface-guide-v1','seen')}catch{}return{ok,awarded:prior?0:100}};window.BunnyAcademy={key,read,balance:()=>{const s=read();return(Number(s.lessonOne.completed)+Number(s.lessonTwo.completed))*100},saveStep:step=>save('lessonOne',step),complete:()=>complete('lessonOne'),saveLessonTwoStep:step=>save('lessonTwo',step),completeLessonTwo:()=>complete('lessonTwo')}})();
